    entries = _read_ledger(args.file)
    return sorted(entries, key=lambda e: e.date)


def _json(value):
    return json.dumps(value) + "\n"


def _totals_lines(totals):
    return [(k, ledger.format_amount(totals[k])) for k in sorted(totals)]


def _cmd_balance(args):
    total = ledger.format_amount(ledger.balance(_read_ledger(args.file)))
    return _json({"balance": total}) if args.json else total + "\n"


def _cmd_summary(args):
    entries = _read_ledger(args.file)
    group = ledger.by_month if args.by == "month" else ledger.by_category
    rows = _totals_lines(group(entries))
    if args.json:
        return _json(dict(rows))
    return "".join("%s  %s\n" % row for row in rows)


def _cmd_list(args):
    entries = ledger.filter_entries(
        _read_ledger(args.file), category=args.category, since=args.since, until=args.until
    )
    entries = sorted(entries, key=lambda e: e.date)
    if args.json:
        return _json([_entry_dict(e) for e in entries])
    return "".join(ledger.format_entry(e) + "\n" for e in entries)


def _entry_dict(entry):
    return {
        "date": entry.date.isoformat(),
        "category": entry.category,
        "amount": ledger.format_amount(entry.amount),
        "note": entry.note,
