def _cmd_export(args):
    entries = _sorted_entries(args)
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        d = _entry_dict(e)
        writer.writerow([d["date"], d["category"], d["amount"], d["note"]])
    return buffer.getvalue()


def _cmd_add(args):
    for label, value in (("date", args.date), ("category", args.category), ("amount", args.amount)):
        if not value or any(ch.isspace() for ch in value):
            raise ParseError(1, "invalid %s %s" % (label, ledger._shorten(value)))
    candidate = "%s %s %s" % (args.date, args.category, args.amount)
    if args.note.strip():
        candidate += " " + args.note
    if len(candidate.splitlines()) != 1:
        raise ParseError(1, "entry must be a single line")
    entries = ledger.parse(candidate)
    if len(entries) != 1:  # e.g. a date starting with '#'
        raise ParseError(1, "invalid entry %s" % ledger._shorten(candidate))
    line = ledger.format_entry(entries[0])

    prefix = b""
    try:
        with open(args.file, "rb") as handle:
            handle.seek(0, os.SEEK_END)
            if handle.tell() > 0:
                handle.seek(-1, os.SEEK_END)
                if handle.read(1) != b"\n":
                    prefix = b"\n"
    except FileNotFoundError:
        pass
    except OSError as exc:
        raise _InputError("cannot read %s: %s" % (args.file, exc))
    try:
        with open(args.file, "ab") as handle:
            handle.write(prefix + (line + "\n").encode("utf-8"))
    except OSError as exc:
        raise _InputError("cannot write %s: %s" % (args.file, exc))
    return line + "\n"


def _silence_stdout():
    """After a failed write, make sure the exit-time flush cannot fail again."""
    try:
        fd = os.open(os.devnull, os.O_WRONLY)
        os.dup2(fd, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _emit(text):
    if not text:
        return 0
    try:
        sys.stdout.write(text)
        sys.stdout.flush()
    except BrokenPipeError:
        _silence_stdout()
        return 2
    except (OSError, ValueError) as exc:
        _silence_stdout()
        print("pennywise: cannot write output: %s" % exc, file=sys.stderr)
        return 2
    return 0


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    parser = _build_parser()
    argv, add_args = _preprocess(argv)
    if add_args is not None:
        if not 4 <= len(add_args) <= 5:
            parser.error("add takes FILE DATE CATEGORY AMOUNT [NOTE]")
        names = ("file", "date", "category", "amount", "note")
        args = argparse.Namespace(command="add", func=_cmd_add, note="")
        for name, value in zip(names, add_args):
            setattr(args, name, value)
    else:
        args = parser.parse_args(argv)
    try:
        output = args.func(args)
    except ParseError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    except _InputError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 2
    return _emit(output)


